slen_full = i2d_SSL_SESSION(s->session, NULL);
if (slen_full == 0 || slen_full > 0xFF00) {
s->state = SSL_ST_ERR;
return -1;
}
senc = OPENSSL_malloc(slen_full);
if (!senc) {
s->state = SSL_ST_ERR;
return -1;
}
