case 16:
dmap = hdigits;
break;
default:
base = 10;
dmap = ddigits;
break;
}
if ( *s == '0'                                  &&
( *( s + 1 ) == 'x' || *( s + 1 ) == 'X' ) )
{
base = 16;
dmap = hdigits;
s   += 2;
}
for ( v = 0; sbitset( dmap, *s ); s++ )
v = v * base + a2i[(int)*s];
if ( end != 0 )
*end = s;
return v;
}

