InsNew( PProfileList  list,
PProfile      profile )
{
PProfile  *old, current;
Long       x;
old     = list;
current = *old;
x       = profile->X;
while ( current )
{
if ( x < current->X )
break;
old     = &current->link;
current = *old;
}
profile->link = current;
*old          = profile;
}

