{
XExtDisplayInfo *info = xvmc_find_display(dpy);
xvmcListSurfaceTypesReply rep;
xvmcListSurfaceTypesReq  *req;
XvMCSurfaceInfo *surface_info = NULL;
*num = 0;
XvMCCheckExtension (dpy, info, NULL);
LockDisplay (dpy);
XvMCGetReq (ListSurfaceTypes, req);
