ABORT_WITH(tt, code);
code = read_DbHeader(tt);
if (code)
ABORT_WITH(tt, code);
code = WhoIsThis(call, tt, cid);
if (code)
ABORT_WITH(tt, PRPERM);
pos = FindByID(tt, id);
if (!pos)
ABORT_WITH(tt, PRNOENT);
code = pr_ReadEntry(tt, 0, pos, &tentry);
if (code)
ABORT_WITH(tt, code);
tflags = tentry.flags;
if (mask & (PR_SF_NGROUPS | PR_SF_NUSERS)) {
