{
pDepth = pScreen->allowedDepths + d;
++ndepth;
for (v = 0; v < pDepth->numVids; v++)
{
pVisual = findVisual (pScreen, pDepth->vids[v]);
if (pVisual && PictureMatchVisual (pScreen, pDepth->depth, pVisual))
++nvisual;
