"Shared_Dirty:   %8lu kB\n"
"Private_Clean:  %8lu kB\n"
"Private_Dirty:  %8lu kB\n"
"Referenced:     %8lu kB\n"
"Anonymous:      %8lu kB\n"
"AnonHugePages:  %8lu kB\n"
"Swap:           %8lu kB\n"
"KernelPageSize: %8lu kB\n"
"MMUPageSize:    %8lu kB\n"
"Locked:         %8lu kB\n",
(vma->vm_end - vma->vm_start) >> 10,
mss.resident >> 10,
(unsigned long)(mss.pss >> (10 + PSS_SHIFT)),
