score2+= FFABS(  s1[x  ] - s1[x  +stride]
- s1[x+1] + s1[x+1+stride])
-FFABS(  s2[x  ] - s2[x  +stride]
- s2[x+1] + s2[x+1+stride]);
}
}
s1+= stride;
s2+= stride;
}
if(c) return score1 + FFABS(score2)*c->avctx->nsse_weight;
else  return score1 + FFABS(score2)*8;
}

