code:
xfs_da_get_buf(
struct xfs_trans	*trans,
struct xfs_inode	*dp,
xfs_dablk_t		bno,
xfs_daddr_t		mappedbno,
struct xfs_buf		**bpp,
int			whichfork)
{
struct xfs_buf		*bp;
struct xfs_buf_map	map;
struct xfs_buf_map	*mapp;
int			nmap;
int			error;
*bpp = NULL;
mapp = &map;
nmap = 1;
error = xfs_dabuf_map(trans, dp, bno, mappedbno, whichfork,
&mapp, &nmap);
if (error) {
if (error == -1)
error = 0;
goto out_free;
}
bp = xfs_trans_get_buf_map(trans, dp->i_mount->m_ddev_targp,
mapp, nmap, 0);
error = bp ? bp->b_error : XFS_ERROR(EIO);
if (error) {
xfs_trans_brelse(trans, bp);
goto out_free;
}
*bpp = bp;
out_free:
if (mapp != &map)
kmem_free(mapp);
return error;
}

