if (decoded_len) {
plain = apr_palloc(r->pool, decoded_len);
decoded_len = apr_base64_decode(plain, encoded);
if (decoded_len > 0 && plain[decoded_len - 1] == '\0')
decoded_len--;
lua_pushlstring(L, plain, decoded_len);
return 1;
}
return 0;
}

