&unused);
if (rc == ENOMEM) {
int newsize;
newsize = zc->zc_nvlist_dst_size;
ASSERT(newsize > size);
kmem_free((void *)(uintptr_t)zc->zc_nvlist_dst, size);
size = newsize;
zc->zc_cookie = cookie;
goto again;
}
if (alloc_size == NULL)
kmem_free((void *)(uintptr_t)zc->zc_nvlist_dst, size);
else
*alloc_size = size;
if (cmd != ZFS_IOC_POOL_CONFIGS)
mutex_exit(&devzvol_mtx);
return (rc);
}

