ffs->raw_descs		= raw_descs;
ffs->raw_descs_length	= data - raw_descs;
ffs->fs_descs_count	= counts[0];
ffs->hs_descs_count	= counts[1];
ffs->ss_descs_count	= counts[2];
ffs->ms_os_descs_count	= os_descs_count;
return 0;
error:
kfree(_data);
return ret;
}

