{
unsigned long flags;
struct snd_seq_event_cell *cell;
if (q == NULL)
return;
spin_lock_irqsave(&q->check_lock, flags);
if (q->check_blocked) {
q->check_again = 1;
spin_unlock_irqrestore(&q->check_lock, flags);
return;
}
