(*out)[track_start - 2] = (track_size >> 8) & 0xff;
(*out)[track_start - 1] = track_size & 0xff;
}
(*out)[10] = (track_count >> 8) & 0xff;
(*out)[11] = track_count & 0xff;
(*out) = realloc((*out), out_ofs);
(*outsize) = out_ofs;
return 0;
}

