{
httpd_send_err( hc, 500, err500title, "", err500form, hc->encodedurl );
return -1;
}
send_mime(
hc, 200, ok200title, hc->encodings, "", hc->type, hc->sb.st_size,
hc->sb.st_mtime );
}
