char *ptr, *optr, *str = strdup (buf);
if (!str) return false;
optr = str;
ptr = strchr (str, '\n');
while (ptr) {
*ptr = '\0';
r_core_cmd (user, optr, 0);
optr = ptr + 1;
ptr = strchr (str, '\n');
}
