error("dup2 /dev/null to STDERR_FILENO: %m");
exit(1);
}
fd_set_noclose_on_exec(STDERR_FILENO);
log_fini();
if (!failed) {
if (conf->chos_loc && !access(conf->chos_loc, X_OK))
