name, FNM_PATHNAME|FNM_PERIOD|FNM_EXTMATCH) ==
0;
if(match && path->name[i].paths == NULL)
goto empty_set;
if(match)
*new = add_subdir(*new, path->name[i].paths);
}
}
if((*new)->count == 0) {
free_subdir(*new);
*new = NULL;
return FALSE;
}
return TRUE;
