set_field_to_legacy_openflow(sf, ofp_version, out);
} else if (is_all_ones(ofpact_set_field_mask(sf), sf->field->n_bytes)) {
set_field_to_set_field(sf, ofp_version, out);
} else {
set_field_to_nxast(sf, out);
