((image->delay != mng_info->delay) ||
(mng_info->framing_mode != mng_info->old_framing_mode)))
{
if (image->delay == mng_info->delay)
{
(void) WriteBlobMSBULong(image,1L);
PNGType(chunk,mng_FRAM);
LogPNGChunk(logging,mng_FRAM,1L);
