if (p->datalen > 255)
atype = SC_APDU_CASE_3_EXT;
else
atype = SC_APDU_CASE_3_SHORT;
sc_format_apdu(card, &apdu, atype, 0x24, 0x01, 0x80);
apdu.lc      = p->datalen;
