for (i = 0; i < n; i++) {
if ((pta = ptaReadStream(fp)) == NULL) {
ptaaDestroy(&ptaa);
return (PTAA *)ERROR_PTR("error reading pta", procName, NULL);
}
ptaaAddPta(ptaa, pta, L_INSERT);
}
return ptaa;
}

