else if (ctx->use_arm_ce)
{
_gcry_aes_armv8_ce_cbc_dec (ctx, iv, outbuf, inbuf, nblocks);
return;
}
#endif
else
{
unsigned char savebuf[BLOCKSIZE] ATTR_ALIGNED_16;
