DEBUG(("\t-C display cropped image (default decoded image)\n"));
DEBUG(("\t-R disable DPB output reordering\n"));
DEBUG(("\t-T to print tag name and exit\n"));
return 0;
}
for (i = 1; i < (u32)(argc-1); i++)
{
