ps_dec_state->aps_ref_pics[0] = NULL;
ps_dec_state->aps_ref_pics[1] = NULL;
ps_dec_state->ps_deint_pic = NULL;
}
}
else
{
s_ctl_reset_op->s_ivd_ctl_reset_op_t.u4_error_code =
IMPEG2D_INIT_NOT_DONE;
}
return(IV_SUCCESS);
}

