ps_dec->u2_motion_type     = 2;
ps_dec->u2_field_dct       = 0;
}
ps_dec->u2_fld_parity          = TOP;
ps_dec->u2_fld_pic             = 0;
ps_dec->u2_frm_pic             = 1;
ps_dec->ps_func_forw_or_back     = gas_impeg2d_func_frm_fw_or_bk;
